1	//! The client-side durable [`Runner`](paigasus_helikon_core::Runner)
2	//! implementation.
3	//!
4	//! [`TemporalRunner`](crate::runner::TemporalRunner) implements
5	//! [`paigasus_helikon_core::Runner`] by starting the durable agent-loop
6	//! workflow (the crate-internal `workflow` module) on a Temporal task queue,
7	//! awaiting its total [`crate::payloads::DurableRunOutcome`], and mapping that
8	//! onto the runner boundary via this crate's `error::outcome_to_run_result`.
9	//! The agent itself executes on the **worker**
10	//! ([`crate::worker::TemporalAgentWorker`]); this runner never runs the agent
11	//! locally — it only needs [`paigasus_helikon_core::Agent::name`] to address
12	//! the registered agent and to seed the session recorder.
13	//!
14	//! # Session semantics (mirrors `TokioRunner`)
15	//!
16	//! `run`/`run_streamed` load persisted history and seed the conversation as
17	//! `history ++ input.messages` (the session owns history, `input` is the new
18	//! turn), and finalize the run's events into the session on **every** exit
19	//! path — success, agent failure, cancellation, timeout, or infrastructure
20	//! error — matching `TokioRunner`'s finalize-on-every-exit guarantee. A
21	//! session read failure is a hard error (the run cannot faithfully resume from
22	//! an unreadable session); session writes are best-effort.
23	
24	use std::sync::{Arc, Mutex};
25	use std::time::Duration;
26	
27	use async_trait::async_trait;
28	use futures_util::stream::{self, StreamExt as _};
29	use paigasus_helikon_core::{
30	    Agent, AgentEvent, AgentInput, CancellationToken, FailureSlot, RunConfig, RunContext, RunError,
31	    RunInterrupt, RunResult, RunResultStreaming, Runner, Session, SessionRecorder,
32	};
33	use temporalio_client::{
34	    Client, WorkflowCancelOptions, WorkflowGetResultOptions, WorkflowStartOptions,
35	};
36	
37	use crate::error::outcome_to_run_result;
38	use crate::payloads::{DriverConfig, DurableRunOutcome, WorkflowInput};
39	
40	/// Configuration for a [`TemporalRunner`].
41	///
42	/// `#[non_exhaustive]`: construct via [`TemporalRunnerConfig::new`] and the
43	/// `with_*` builder methods, not a struct literal — this keeps adding a field
44	/// (e.g. the private `ctx_seed`) a non-breaking change.
45	#[derive(Debug, Clone)]
46	#[non_exhaustive]
47	pub struct TemporalRunnerConfig {
48	    /// Task queue the durable workflow (and its worker) are served on. Must
49	    /// match the task queue the [`crate::worker::TemporalAgentWorker`] polls.
50	    pub task_queue: String,
51	    /// Workflow id assigned per run.
52	    ///
53	    /// `None` (the default) mints a fresh `helikon-run-{uuid-v4}` per run,
54	    /// client-side. Set this only when the caller needs a deterministic
55	    /// workflow id (e.g. idempotent start / dedup); reusing the same id across
56	    /// concurrent runs is a Temporal id-reuse conflict.
57	    pub workflow_id: Option<String>,
58	    /// Backstop margin added to `RunConfig::timeout` when setting the hard
59	    /// Temporal **workflow-execution** timeout.
60	    ///
61	    /// The run deadline itself is a durable timer *inside* the workflow (so an
62	    /// expiry returns `TimedOut` with events-so-far); this execution timeout is
63	    /// only a safety backstop above it and would discard the outcome, so it is
64	    /// set generously above the durable timer. Default 60s.
65	    pub execution_timeout_margin: Duration,
66	    /// Optional request-scoped seed forwarded to the worker's seeded ctx
67	    /// factory. Private: set via [`Self::with_ctx_seed`]. Default `None`.
68	    ctx_seed: Option<serde_json::Value>,
69	}
70	
71	impl TemporalRunnerConfig {
72	    /// Construct a config for `task_queue` with the default workflow-id policy
73	    /// (`helikon-run-{uuid}`) and a 60s execution-timeout margin.
74	    pub fn new(task_queue: impl Into<String>) -> Self {
75	        Self {
76	            task_queue: task_queue.into(),
77	            workflow_id: None,
78	            execution_timeout_margin: Duration::from_secs(60),
79	            ctx_seed: None,
80	        }
81	    }
82	
83	    /// Attach a request-scoped seed forwarded (explicitly) to the worker's
84	    /// seeded ctx factory for every run this config drives. Recorded in
85	    /// Temporal history — keep it small and secret-free.
86	    pub fn with_ctx_seed(mut self, seed: serde_json::Value) -> Self {
87	        self.ctx_seed = Some(seed);
88	        self
89	    }
90	}
91	
92	/// A durable, Temporal-backed [`Runner`].
93	///
94	/// Holds a connected [`temporalio_client::Client`] and a
95	/// [`TemporalRunnerConfig`]; each `run` starts one durable workflow execution
96	/// on the configured task queue. Construct via [`TemporalRunner::new`].
97	pub struct TemporalRunner {
98	    client: Client,
99	    config: TemporalRunnerConfig,
100	}
101	
102	impl TemporalRunner {
103	    /// Build a runner from a connected client and its configuration.
104	    pub fn new(client: Client, config: TemporalRunnerConfig) -> Self {
105	        Self { client, config }
106	    }
107	
108	    /// Run the durable workflow to completion, racing the client's cancel
109	    /// token against the awaited result: a fired token requests cooperative
110	    /// workflow cancellation, after which the workflow still returns a total
111	    /// (`Cancelled`) outcome.
112	    async fn run_workflow(
113	        &self,
114	        input: WorkflowInput,
115	        timeout: Option<Duration>,
116	        cancel: CancellationToken,
117	    ) -> Result<DurableRunOutcome, RunError> {
118	        // Workflow id is minted client-side (never inside the workflow, which
119	        // must stay deterministic).
120	        let workflow_id = self
121	            .config
122	            .workflow_id
123	            .clone()
124	            .unwrap_or_else(|| format!("helikon-run-{}", uuid::Uuid::new_v4()));
125	
126	        let execution_timeout =
127	            timeout.map(|d| d.saturating_add(self.config.execution_timeout_margin));
128	        let start_opts = WorkflowStartOptions::new(self.config.task_queue.clone(), workflow_id)
129	            .maybe_execution_timeout(execution_timeout)
130	            .build();
131	
132	        let handle = self
133	            .client
134	            .start_workflow(
135	                crate::workflow::DurableAgentWorkflow::run,
136	                input,
137	                start_opts,
138	            )
139	            .await
140	            .map_err(|e| {
141	                RunError::Other(anyhow::anyhow!("failed to start temporal workflow: {e}"))
142	            })?;
143	
144	        let get_result = handle.get_result(WorkflowGetResultOptions::default());
145	        tokio::pin!(get_result);
146	        let mut requested_cancel = false;
147	        let outcome = loop {
148	            tokio::select! {
149	                result = &mut get_result => break result,
150	                // Once the run's cancel token fires, request cooperative
151	                // workflow cancellation once, then keep awaiting the (now
152	                // `Cancelled`) total outcome.
153	                () = cancel.cancelled(), if !requested_cancel => {
154	                    requested_cancel = true;
155	                    let _ = handle.cancel(WorkflowCancelOptions::default()).await;
156	                }
157	            }
158	        };
159	
160	        outcome.map_err(|e| RunError::Other(anyhow::anyhow!("temporal workflow failed: {e}")))
161	    }
162	
163	    /// Shared run path for both [`Runner::run`] and [`Runner::run_streamed`].
164	    ///
165	    /// Returns the run's events plus its mapped terminal result. The outer
166	    /// `Err` is reserved for a session **read** failure (load fails before the
167	    /// run starts); every other exit — including workflow start/await
168	    /// infrastructure failures — finalizes the session recorder and reports its
169	    /// outcome as the inner `Result`.
170	    async fn run_inner<Ctx>(
171	        &self,
172	        agent: &(dyn Agent<Ctx> + '_),
173	        ctx: RunContext<Ctx>,
174	        input: AgentInput,
175	        config: RunConfig,
176	    ) -> Result<(Vec<AgentEvent>, Result<RunResult, RunError>), RunError>
177	    where
178	        Ctx: Send + Sync + 'static,
179	    {
180	        let timeout = config.timeout;
181	        let max_turns = config.max_turns;
182	        let parallel_tool_call_limit = config.parallel_tool_call_limit;
183	
184	        let ctx = ctx.with_run_config(config);
185	        let cancel = ctx.cancel().clone();
186	        let session = ctx.session().clone();
187	
188	        // Session read failure is a hard error (mirrors `TokioRunner`).
189	        let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
190	
191	        let workflow_input = WorkflowInput {
192	            agent_name: agent.name().to_owned(),
193	            conversation: merged.messages,
194	            config: DriverConfig {
195	                max_turns,
196	                parallel_tool_call_limit: parallel_tool_call_limit.map(|n| n.get()),
197	            },
198	            timeout_ms: timeout.map(|d| d.as_millis() as u64),
199	            ctx_seed: self.config.ctx_seed.clone(),
200	        };
201	
202	        match self.run_workflow(workflow_input, timeout, cancel).await {
203	            Ok(outcome) => {
204	                {
205	                    let mut rec = recorder.lock().expect("session recorder mutex poisoned");
206	                    for event in &outcome.events {
207	                        rec.observe(event);
208	                    }
209	                }
210	                finalize(&session, &recorder).await;
211	                let events = outcome.events.clone();
212	                Ok((events, outcome_to_run_result(outcome)))
213	            }
214	            Err(infra) => {
215	                // Infra failure: still finalize (the recorder holds this turn's
216	                // new-turn input) before surfacing the error.
217	                finalize(&session, &recorder).await;
218	                Ok((Vec::new(), Err(infra)))
219	            }
220	        }
221	    }
222	}
223	
224	#[async_trait]
225	impl<Ctx> Runner<Ctx> for TemporalRunner
226	where
227	    Ctx: Send + Sync + 'static,
228	{
229	    async fn run(
230	        &self,
231	        agent: &(dyn Agent<Ctx> + '_),
232	        ctx: RunContext<Ctx>,
233	        input: AgentInput,
234	        config: RunConfig,
235	    ) -> Result<RunResult, RunError> {
236	        let (_events, result) = self.run_inner(agent, ctx, input, config).await?;
237	        result
238	    }
239	
240	    /// **Buffered, not live.** The durable workflow runs to completion first;
241	    /// the returned stream then replays the already-recorded
242	    /// [`AgentEvent`]s as an immediate, finite stream. Because persistence
243	    /// happened *before* the stream exists (a strictly stronger guarantee than
244	    /// the trait's warning), dropping the stream early loses nothing. Live
245	    /// token streaming across the workflow boundary is future work.
246	    ///
247	    /// On a failed run the terminal error is wired into the returned handle's
248	    /// [`FailureSlot`] and a terminal `RunFailed` event is guaranteed present,
249	    /// so [`RunResultStreaming::collect`] surfaces the typed
250	    /// [`RunError::Agent`] — matching `TokioRunner`.
251	    async fn run_streamed(
252	        &self,
253	        agent: &(dyn Agent<Ctx> + '_),
254	        ctx: RunContext<Ctx>,
255	        input: AgentInput,
256	        config: RunConfig,
257	    ) -> Result<RunResultStreaming, RunError> {
258	        let (mut events, result) = self.run_inner(agent, ctx, input, config).await?;
259	
260	        let failure = FailureSlot::new();
261	        let terminal = synthetic_terminal_event(&result);
262	        // Move the structured error into the slot only for an agent failure;
263	        // the event itself was already rendered above.
264	        if let Err(RunError::Agent(err)) = result {
265	            failure.set(err);
266	        }
267	
268	        // `collect()` only reads the failure slot once it observes a terminal
269	        // `RunFailed` in the stream. The durable event log already carries one
270	        // for `AgentFailed` runs; synthesize one for the terminal states that do
271	        // not (cancellation/timeout/infra), so a failed run never collects as
272	        // `Ok`. `append_synthetic_terminal` owns the guard that stops this from
273	        // appending a *second* terminal (SMA-422).
274	        append_synthetic_terminal(&mut events, terminal);
275	
276	        Ok(RunResultStreaming::with_failure(
277	            stream::iter(events).boxed(),
278	            failure,
279	        ))
280	    }
281	}
282	
283	/// The terminal frame [`Runner::run_streamed`] synthesizes when a run ends
284	/// without one of its own, or `None` when the run succeeded.
285	///
286	/// Cancellation and timeout render through [`RunInterrupt::terminal_event`],
287	/// **not** through [`RunError`]'s `Display`. The two disagree — `RunError::Cancelled`
288	/// displays as `"cancelled"` while the canonical synthesized frame says
289	/// `"run cancelled"` — so going through `Display` here would make this runner emit
290	/// different text than `TokioRunner` for the same event. One rendering, one place
291	/// (SMA-422, SMA-515).
292	fn synthetic_terminal_event(result: &Result<RunResult, RunError>) -> Option<AgentEvent> {
293	    match result {
294	        Ok(_) => None,
295	        Err(RunError::Agent(err)) => Some(AgentEvent::RunFailed {
296	            error: err.to_string(),
297	        }),
298	        Err(RunError::Cancelled) => Some(RunInterrupt::Cancelled.terminal_event()),
299	        Err(RunError::Timeout) => Some(RunInterrupt::TimedOut.terminal_event()),
300	        // `RunError` is `#[non_exhaustive]` and foreign, so this arm is required.
301	        // Infrastructure failures have no canonical interrupt text; their own
302	        // message is the most informative thing available. Not a `RunInterrupt`,
303	        // so the frame is built here rather than in core.
304	        Err(other) => Some(AgentEvent::RunFailed {
305	            error: other.to_string(),
306	        }),
307	    }
308	}
309	
310	/// Append `event` as the run's terminal frame, unless the durable event log
311	/// already ends in one.
312	///
313	/// The guard is load-bearing (SMA-422, closing SMA-421): a status that mapped to
314	/// `Err` while the event log ended in `RunCompleted` must not append a second
315	/// terminal. It tests for *any* terminal via [`AgentEvent::is_terminal`], not
316	/// just `RunFailed`.
317	fn append_synthetic_terminal(events: &mut Vec<AgentEvent>, event: Option<AgentEvent>) {
318	    if let Some(event) = event {
319	        if !events.last().is_some_and(AgentEvent::is_terminal) {
320	            events.push(event);
321	        }
322	    }
323	}
324	
325	/// Snapshot the session into the merged input and seed a recorder with the
326	/// run's new-turn messages. A read failure is a hard error: the run cannot
327	/// faithfully resume from an unreadable session. (Mirrors
328	/// `TokioRunner::load_and_record`.)
329	async fn load_and_record(
330	    session: &Arc<dyn Session>,
331	    agent_name: &str,
332	    input: AgentInput,
333	) -> Result<(AgentInput, Arc<Mutex<SessionRecorder>>), RunError> {
334	    let snapshot = session
335	        .snapshot()
336	        .await
337	        .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
338	    let mut recorder = SessionRecorder::new(agent_name);
339	    recorder.record_input(&input.messages);
340	
341	    let mut merged = AgentInput::new();
342	    merged.messages = snapshot.messages;
343	    merged.messages.extend(input.messages);
344	    Ok((merged, Arc::new(Mutex::new(recorder))))
345	}
346	
347	/// Post-run finalization: drain the recorder and append the run's events.
348	/// Persistence is best-effort — an append error is logged, never propagated.
349	/// (Mirrors `TokioRunner::finalize`.)
350	async fn finalize(session: &Arc<dyn Session>, recorder: &Arc<Mutex<SessionRecorder>>) {
351	    let events = recorder
352	        .lock()
353	        .expect("session recorder mutex poisoned")
354	        .drain();
355	    if let Err(e) = session.append(&events).await {
356	        tracing::warn!(
357	            target: "paigasus::runtime_temporal::runner",
358	            error = %e,
359	            "session persistence failed during finalize; run outcome unaffected"
360	        );
361	    }
362	}
363	
364	#[cfg(test)]
365	mod tests {
366	    use super::*;
367	    use paigasus_helikon_core::{AgentError, TokenUsage};
368	
369	    /// Unwrap a synthesized terminal to its message, asserting the variant on
370	    /// the way through — something the old `-> Option<String>` signature made
371	    /// impossible.
372	    fn terminal_text(ev: Option<AgentEvent>) -> Option<String> {
373	        match ev {
374	            Some(AgentEvent::RunFailed { error }) => Some(error),
375	            Some(other) => panic!("synthesized terminal must be RunFailed, got {other:?}"),
376	            None => None,
377	        }
378	    }
379	
380	    #[test]
381	    fn with_ctx_seed_stores_seed() {
382	        let cfg =
383	            TemporalRunnerConfig::new("q").with_ctx_seed(serde_json::json!({"tenant": "acme"}));
384	        assert_eq!(cfg.ctx_seed, Some(serde_json::json!({"tenant": "acme"})));
385	    }
386	
387	    #[test]
388	    fn ctx_seed_defaults_none() {
389	        assert_eq!(TemporalRunnerConfig::new("q").ctx_seed, None);
390	    }
391	
392	    /// A cancelled run's synthesized terminal must carry the *canonical*
393	    /// interrupt text, so this runner and `TokioRunner` are indistinguishable
394	    /// to a stream consumer. Routing through `RunError`'s `Display` instead
395	    /// would silently emit "cancelled" here and "run cancelled" there.
396	    #[test]
397	    fn cancelled_renders_the_canonical_interrupt_message() {
398	        let message = terminal_text(synthetic_terminal_event(&Err(RunError::Cancelled)));
399	        assert_eq!(
400	            message.as_deref(),
401	            Some(RunInterrupt::Cancelled.terminal_message())
402	        );
403	        assert_eq!(message.as_deref(), Some("run cancelled"));
404	        assert_ne!(
405	            message,
406	            Some(RunError::Cancelled.to_string()),
407	            "must not fall through to RunError's Display, which says \"cancelled\""
408	        );
409	    }
410	
411	    #[test]
