413	        assert_eq!(
414	            terminal_text(synthetic_terminal_event(&Err(RunError::Timeout))).as_deref(),
415	            Some(RunInterrupt::TimedOut.terminal_message())
416	        );
417	    }
418	
419	    #[test]
420	    fn success_synthesizes_no_terminal_event() {
